        console.log(`[Dr.'s Engine] \uBA85\uC18C ID ${landmarkId}\uC758 \uD64D\uBCF4 \uBB38\uAD6C\uAC00 \uC2E0\uADDC \uC790\uC0B0\uC73C\uB85C DB\uC5D0 \uB4F1\uB85D\uB418\uC5C8\uC2B5\uB2C8\uB2E4.`);
